INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-chaloem-phra-kiat-17-160',
        'มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)',
        'The Golden Relic Stupa of Chaloem Phra Kiat (อีสานใต้ขอมโบราณ)',
        'sacred',
        'บุรีรัมย์ (ไทย)',
        'Buri Ram (Thailand)',
        'เฉลิมพระเกียรติ',
        'Chaloem Phra Kiat',
        14.5767,
        102.9569,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน บุรีรัมย์ (ไทย) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว อีสานใต้ขอมโบราณ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Buri Ram (Thailand), serving as the spiritual heart of ancestral อีสานใต้ขอมโบราณ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค บุรีรัมย์ (ไทย) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Buri Ram (Thailand), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน เฉลิมพระเกียรติ',
        'Remove footwear and maintain silence within the inner terrace of Chaloem Phra Kiat.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-chaloem-phra-kiat-17-160',
        'วิญญาณสตรีชุดขาวแห่งเส้นทางโบราณ เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)',
        'The White Lady Specter of Chaloem Phra Kiat (อีสานใต้ขอมโบราณ)',
        'ghost',
        'บุรีรัมย์ (ไทย)',
        'Buri Ram (Thailand)',
        'เฉลิมพระเกียรติ',
        'Chaloem Phra Kiat',
        14.5767,
        102.9569,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น บุรีรัมย์ (ไทย) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ เฉลิมพระเกียรติ',
        'A chilling paranormal account from Buri Ram (Thailand). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Chaloem Phra Kiat.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว อีสานใต้ขอมโบราณ ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of อีสานใต้ขอมโบราณ oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ เฉลิมพระเกียรติ',
        'Never whistle or look back if hearing whispers along twilight pathways in Chaloem Phra Kiat.',
        'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"วิญญาณสตรีชุดขาวแห่งเส้นทางโบราณ เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"เรื่องเล่าวิญญาณและปราสาทหลอนโบราณ","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-chaloem-phra-kiat-17-160',
        'อสุรกายพญาเงาแห่งพงไพร เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)',
        'The Shadow Beast of Chaloem Phra Kiat (อีสานใต้ขอมโบราณ)',
        'monster',
        'บุรีรัมย์ (ไทย)',
        'Buri Ram (Thailand)',
        'เฉลิมพระเกียรติ',
        'Chaloem Phra Kiat',
        14.5767,
        102.9569,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน บุรีรัมย์ (ไทย) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ เฉลิมพระเกียรติ',
        'Eyewitness reports of a formidable cryptid stalking Buri Ram (Thailand). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Chaloem Phra Kiat.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว อีสานใต้ขอมโบราณ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native อีสานใต้ขอมโบราณ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ เฉลิมพระเกียรติ',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Chaloem Phra Kiat.',
        'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"อสุรกายพญาเงาแห่งพงไพร เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"การค้นพบสิ่งมีชีวิตลี้ลับและอสุรกายโบราณ","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-chaloem-phra-kiat-17-160',
        'คำสาปศิลาจารึกและอาถรรพ์ชะตากรรม เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)',
        'The Inscribed Hex and Tragic Fate of Chaloem Phra Kiat (อีสานใต้ขอมโบราณ)',
        'curse',
        'บุรีรัมย์ (ไทย)',
        'Buri Ram (Thailand)',
        'เฉลิมพระเกียรติ',
        'Chaloem Phra Kiat',
        14.5767,
        102.9569,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง บุรีรัมย์ (ไทย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน เฉลิมพระเกียรติ',
        'A grim cautionary curse chronicle from Buri Ram (Thailand). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Chaloem Phra Kiat.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว อีสานใต้ขอมโบราณ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of อีสานใต้ขอมโบราณ, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ เฉลิมพระเกียรติ',
        'Never remove stones, relics, or votive offerings from Chaloem Phra Kiat.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"คำสาปศิลาจารึกและอาถรรพ์ชะตากรรม เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-chaloem-phra-kiat-17-160',
        'มหาปราการหินเมกะลิธและแนวสุริยะ เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)',
        'The Megalithic Solar Alignments of Chaloem Phra Kiat (อีสานใต้ขอมโบราณ)',
        'legend',
        'บุรีรัมย์ (ไทย)',
        'Buri Ram (Thailand)',
        'เฉลิมพระเกียรติ',
        'Chaloem Phra Kiat',
        14.5767,
        102.9569,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง บุรีรัมย์ (ไทย) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว อีสานใต้ขอมโบราณ ใน เฉลิมพระเกียรติ',
        'A legendary monumental marvel in Buri Ram (Thailand). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral อีสานใต้ขอมโบราณ engineers in Chaloem Phra Kiat.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ บุรีรัมย์ (ไทย) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Buri Ram (Thailand), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ เฉลิมพระเกียรติ',
        'Do not deface, carve, or displace ancient stones in Chaloem Phra Kiat.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"มหาปราการหินเมกะลิธและแนวสุริยะ เฉลิมพระเกียรติ (อีสานใต้ขอมโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

