      ) VALUES (
        'pin-ghost-noboribetsu-17-165',
        'เงาไร้หน้าที่บานหน้าต่างค่ำคืน โนโบริเบ็ตสึ (ไอนุ)',
        'The Faceless Window Silhouette of Noboribetsu (ไอนุ)',
        'ghost',
        'ฮอกไกโด (ญี่ปุ่น)',
        'Hokkaido (Japan)',
        'โนโบริเบ็ตสึ',
        'Noboribetsu',
        42.4267,
        141.1367,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น ฮอกไกโด (ญี่ปุ่น) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ โนโบริเบ็ตสึ',
        'A chilling paranormal account from Hokkaido (Japan). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Noboribetsu.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว ไอนุ ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of ไอนุ oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ โนโบริเบ็ตสึ',
        'Never whistle or look back if hearing whispers along twilight pathways in Noboribetsu.',
        'https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg","title":"เงาไร้หน้าที่บานหน้าต่างค่ำคืน โนโบริเบ็ตสึ (ไอนุ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LbCWDUZhSFc","title":"ปริศนาดวงวิญญาณและคฤหาสน์ต้องห้าม","thumbnail":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-noboribetsu-17-165',
        'ปีศาจจำแลงร่างล่อลวงคนเดินทาง โนโบริเบ็ตสึ (ไอนุ)',
        'The Deceptive Shapeshifting Stalker of Noboribetsu (ไอนุ)',
        'monster',
        'ฮอกไกโด (ญี่ปุ่น)',
        'Hokkaido (Japan)',
        'โนโบริเบ็ตสึ',
        'Noboribetsu',
        42.4267,
        141.1367,
        'whisper',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน ฮอกไกโด (ญี่ปุ่น) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ โนโบริเบ็ตสึ',
        'Eyewitness reports of a formidable cryptid stalking Hokkaido (Japan). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Noboribetsu.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว ไอนุ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native ไอนุ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ โนโบริเบ็ตสึ',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Noboribetsu.',
        'https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg","title":"ปีศาจจำแลงร่างล่อลวงคนเดินทาง โนโบริเบ็ตสึ (ไอนุ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8W-DjTLd0mo","title":"สารคดี สัตว์ประหลาดในตำนานและสิ่งลี้ลับ","thumbnail":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-noboribetsu-17-165',
        'อาถรรพ์เรือวิญญาณและกะลาสีต้องสาป โนโบริเบ็ตสึ (ไอนุ)',
        'The Spectral Vessel Curse of Noboribetsu (ไอนุ)',
        'curse',
        'ฮอกไกโด (ญี่ปุ่น)',
        'Hokkaido (Japan)',
        'โนโบริเบ็ตสึ',
        'Noboribetsu',
        42.4267,
        141.1367,
        'water_spirit',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง ฮอกไกโด (ญี่ปุ่น) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน โนโบริเบ็ตสึ',
        'A grim cautionary curse chronicle from Hokkaido (Japan). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Noboribetsu.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ไอนุ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ไอนุ, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ โนโบริเบ็ตสึ',
        'Never remove stones, relics, or votive offerings from Noboribetsu.',
        'https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg","title":"อาถรรพ์เรือวิญญาณและกะลาสีต้องสาป โนโบริเบ็ตสึ (ไอนุ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TbB9KfaRq70","title":"อาถรรพ์วัตถุต้องคำสาปและโศกนาฏกรรม","thumbnail":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
