INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-jongno-17-166',
        'คำสาปโลงศพและมัมมี่ผู้ล่วงละเมิด จงโน (โชซอน)',
        'The Desecrated Tomb Hex of Jongno (โชซอน)',
        'curse',
        'โซล (เกาหลีใต้)',
        'Seoul (South Korea)',
        'จงโน',
        'Jongno',
        37.6028,
        126.9494,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง โซล (เกาหลีใต้) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน จงโน',
        'A grim cautionary curse chronicle from Seoul (South Korea). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Jongno.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว โชซอน เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of โชซอน, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ จงโน',
        'Never remove stones, relics, or votive offerings from Jongno.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"คำสาปโลงศพและมัมมี่ผู้ล่วงละเมิด จงโน (โชซอน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-jongno-17-166',
        'บ่อน้ำพุศักดิ์สิทธิ์ไร้ก้นแห่งตำนาน จงโน (โชซอน)',
        'The Bottomless Sacred Cenote of Jongno (โชซอน)',
        'legend',
        'โซล (เกาหลีใต้)',
        'Seoul (South Korea)',
        'จงโน',
        'Jongno',
        37.6028,
        126.9494,
        'water_spirit',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง โซล (เกาหลีใต้) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว โชซอน ใน จงโน',
        'A legendary monumental marvel in Seoul (South Korea). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral โชซอน engineers in Jongno.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ โซล (เกาหลีใต้) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Seoul (South Korea), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ จงโน',
        'Do not deface, carve, or displace ancient stones in Jongno.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"บ่อน้ำพุศักดิ์สิทธิ์ไร้ก้นแห่งตำนาน จงโน (โชซอน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-seogwipo-17-167',
        'เทวาลัยโบราณแห่งมหาเทวะ ซอกวิโพ (ทัมราโบราณ)',
        'The Ancient Chola Shiva Shrine of Seogwipo (ทัมราโบราณ)',
        'sacred',
        'เชจู (เกาหลีใต้)',
        'Jeju (South Korea)',
        'ซอกวิโพ',
        'Seogwipo',
        33.2992,
        126.575,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน เชจู (เกาหลีใต้) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว ทัมราโบราณ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Jeju (South Korea), serving as the spiritual heart of ancestral ทัมราโบราณ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค เชจู (เกาหลีใต้) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Jeju (South Korea), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน ซอกวิโพ',
        'Remove footwear and maintain silence within the inner terrace of Seogwipo.',
        'https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg","title":"เทวาลัยโบราณแห่งมหาเทวะ ซอกวิโพ (ทัมราโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EE1yv4CRjzY","title":"เปิดประวัติศาสตร์ มหาเจดีย์ศักดิ์สิทธิ์พันปี","thumbnail":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-seogwipo-17-167',
        'ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ ซอกวิโพ (ทัมราโบราณ)',
        'The Will-o''-the-Wisp Ghost Light of Seogwipo (ทัมราโบราณ)',
        'ghost',
        'เชจู (เกาหลีใต้)',
        'Jeju (South Korea)',
        'ซอกวิโพ',
        'Seogwipo',
        33.2992,
        126.575,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น เชจู (เกาหลีใต้) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ ซอกวิโพ',
        'A chilling paranormal account from Jeju (South Korea). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Seogwipo.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว ทัมราโบราณ ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of ทัมราโบราณ oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ ซอกวิโพ',
        'Never whistle or look back if hearing whispers along twilight pathways in Seogwipo.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ ซอกวิโพ (ทัมราโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-seogwipo-17-167',
        'อสูรครึ่งคนครึ่งสัตว์น้ำแห่งถ้ำมืด ซอกวิโพ (ทัมราโบราณ)',
        'The Amphibious Troglodyte of Seogwipo (ทัมราโบราณ)',
        'monster',
        'เชจู (เกาหลีใต้)',
        'Jeju (South Korea)',
        'ซอกวิโพ',
        'Seogwipo',
        33.2992,
        126.575,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน เชจู (เกาหลีใต้) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ ซอกวิโพ',
        'Eyewitness reports of a formidable cryptid stalking Jeju (South Korea). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Seogwipo.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว ทัมราโบราณ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native ทัมราโบราณ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ ซอกวิโพ',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Seogwipo.',
        'https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg","title":"อสูรครึ่งคนครึ่งสัตว์น้ำแห่งถ้ำมืด ซอกวิโพ (ทัมราโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xo_fMcSLp7Q","title":"สัตว์ลึกลับแห่งพงไพรและสายน้ำโบราณ","thumbnail":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg"}]'
      );

