        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-chengdu-17-168',
        'สัตว์ร้ายดูดเลือดแห่งทุ่งรกร้าง เฉิงตู (สู่ฮั่นโบราณ)',
        'The Night Livestock Stalker of Chengdu (สู่ฮั่นโบราณ)',
        'monster',
        'เสฉวน (จีน)',
        'Sichuan (China)',
        'เฉิงตู',
        'Chengdu',
        30.6136,
        104.0197,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน เสฉวน (จีน) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ เฉิงตู',
        'Eyewitness reports of a formidable cryptid stalking Sichuan (China). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Chengdu.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว สู่ฮั่นโบราณ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native สู่ฮั่นโบราณ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ เฉิงตู',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Chengdu.',
        'https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg","title":"สัตว์ร้ายดูดเลือดแห่งทุ่งรกร้าง เฉิงตู (สู่ฮั่นโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8W-DjTLd0mo","title":"สารคดี สัตว์ประหลาดในตำนานและสิ่งลี้ลับ","thumbnail":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg"}]'
      );

