        112.9381,
        'jungle_curse',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง ชวาตะวันออก (อินโดนีเซีย) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว มัชปาหิต ใน ภูเขาไฟโบรโม',
        'A legendary monumental marvel in East Java (Indonesia). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral มัชปาหิต engineers in Mount Bromo.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ ชวาตะวันออก (อินโดนีเซีย) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in East Java (Indonesia), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ ภูเขาไฟโบรโม',
        'Do not deface, carve, or displace ancient stones in Mount Bromo.',
        'https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg","title":"นครโบราณที่สาบสูญใต้ผืนป่า ภูเขาไฟโบรโม (มัชปาหิต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qD-80cmvTts","title":"มรดกตำนานและนครสาบสูญแห่งประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-baguio-18-172',
        'อารามโบราณพิทักษ์ผืนป่า บากีโอ (คอร์ดิลเลรา)',
        'The Sacred Mountain Hermitage of Baguio (คอร์ดิลเลรา)',
        'sacred',
        'ลูซอน (ฟิลิปปินส์)',
        'Luzon (Philippines)',
        'บากีโอ',
        'Baguio',
        16.4172,
        120.6261,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน ลูซอน (ฟิลิปปินส์) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว คอร์ดิลเลรา เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Luzon (Philippines), serving as the spiritual heart of ancestral คอร์ดิลเลรา heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค ลูซอน (ฟิลิปปินส์) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Luzon (Philippines), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน บากีโอ',
        'Remove footwear and maintain silence within the inner terrace of Baguio.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"อารามโบราณพิทักษ์ผืนป่า บากีโอ (คอร์ดิลเลรา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-baguio-18-172',
        'ดวงวิญญาณผู้พิทักษ์คฤหาสน์เก่า บากีโอ (คอร์ดิลเลรา)',
        'The Ancestral Manor Shade of Baguio (คอร์ดิลเลรา)',
        'ghost',
        'ลูซอน (ฟิลิปปินส์)',
        'Luzon (Philippines)',
        'บากีโอ',
        'Baguio',
        16.4172,
        120.6261,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น ลูซอน (ฟิลิปปินส์) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ บากีโอ',
        'A chilling paranormal account from Luzon (Philippines). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Baguio.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว คอร์ดิลเลรา ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of คอร์ดิลเลรา oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ บากีโอ',
        'Never whistle or look back if hearing whispers along twilight pathways in Baguio.',
        'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"ดวงวิญญาณผู้พิทักษ์คฤหาสน์เก่า บากีโอ (คอร์ดิลเลรา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"เรื่องเล่าวิญญาณและปราสาทหลอนโบราณ","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
