        'A legendary monumental marvel in Luzon (Philippines). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral คอร์ดิลเลรา engineers in Baguio.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ ลูซอน (ฟิลิปปินส์) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Luzon (Philippines), representing an indelible testament to ancient cultural zenith and architectural mastery.',
