INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-imperial-hue-18-173',
        'พรายน้ำคร่ำครวญริมสายน้ำ นครหลวงเว้ (ราชวงศ์เหงียน)',
        'The Weeping Water Banshee of Imperial Hue (ราชวงศ์เหงียน)',
        'ghost',
        'เว้ (เวียดนาม)',
        'Hue (Vietnam)',
        'นครหลวงเว้',
        'Imperial Hue',
        16.4937,
        107.5609,
        'water_spirit',
        'เรื่องเล่าสยองขวัญประจำถิ่น เว้ (เวียดนาม) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ นครหลวงเว้',
        'A chilling paranormal account from Hue (Vietnam). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Imperial Hue.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว ราชวงศ์เหงียน ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of ราชวงศ์เหงียน oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ นครหลวงเว้',
        'Never whistle or look back if hearing whispers along twilight pathways in Imperial Hue.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"พรายน้ำคร่ำครวญริมสายน้ำ นครหลวงเว้ (ราชวงศ์เหงียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-imperial-hue-18-173',
        'มนุษย์วานรยักษ์แห่งป่าดึกดำบรรพ์ นครหลวงเว้ (ราชวงศ์เหงียน)',
        'The Primeval Forest Ape Cryptid of Imperial Hue (ราชวงศ์เหงียน)',
        'monster',
        'เว้ (เวียดนาม)',
        'Hue (Vietnam)',
        'นครหลวงเว้',
        'Imperial Hue',
        16.4937,
        107.5609,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน เว้ (เวียดนาม) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ นครหลวงเว้',
        'Eyewitness reports of a formidable cryptid stalking Hue (Vietnam). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Imperial Hue.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว ราชวงศ์เหงียน ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native ราชวงศ์เหงียน folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ นครหลวงเว้',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Imperial Hue.',
        'https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg","title":"มนุษย์วานรยักษ์แห่งป่าดึกดำบรรพ์ นครหลวงเว้ (ราชวงศ์เหงียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xo_fMcSLp7Q","title":"สัตว์ลึกลับแห่งพงไพรและสายน้ำโบราณ","thumbnail":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-imperial-hue-18-173',
        'คำสาปแผ่นดินและเมืองร้างโบราณ นครหลวงเว้ (ราชวงศ์เหงียน)',
        'The Desolation Curse of Imperial Hue (ราชวงศ์เหงียน)',
        'curse',
        'เว้ (เวียดนาม)',
        'Hue (Vietnam)',
        'นครหลวงเว้',
        'Imperial Hue',
        16.4937,
        107.5609,
        'creepy_wind',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง เว้ (เวียดนาม) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน นครหลวงเว้',
        'A grim cautionary curse chronicle from Hue (Vietnam). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Imperial Hue.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ราชวงศ์เหงียน เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ราชวงศ์เหงียน, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ นครหลวงเว้',
        'Never remove stones, relics, or votive offerings from Imperial Hue.',
        'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"คำสาปแผ่นดินและเมืองร้างโบราณ นครหลวงเว้ (ราชวงศ์เหงียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"คำสาปแห่งราชวงศ์และสิ่งเร้นลับทางประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-imperial-hue-18-173',
        'ถ้ำภาพเขียนสีโบราณหมื่นปี นครหลวงเว้ (ราชวงศ์เหงียน)',
        'The Prehistoric Painted Caverns of Imperial Hue (ราชวงศ์เหงียน)',
        'legend',
        'เว้ (เวียดนาม)',
        'Hue (Vietnam)',
        'นครหลวงเว้',
        'Imperial Hue',
        16.4937,
        107.5609,
        'whisper',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง เว้ (เวียดนาม) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว ราชวงศ์เหงียน ใน นครหลวงเว้',
        'A legendary monumental marvel in Hue (Vietnam). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral ราชวงศ์เหงียน engineers in Imperial Hue.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ เว้ (เวียดนาม) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Hue (Vietnam), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ นครหลวงเว้',
        'Do not deface, carve, or displace ancient stones in Imperial Hue.',
        'https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg","title":"ถ้ำภาพเขียนสีโบราณหมื่นปี นครหลวงเว้ (ราชวงศ์เหงียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sB7nFq5K_3M","title":"สารคดี อารยธรรมและตำนานโบราณ","thumbnail":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
