        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-angkor-wat-18-175',
        'กำแพงศิลาและป้อมปราการแห่งกษัตริย์ พระนครวัด (เขมรโบราณ)',
        'The Cyclopean Stone Fortresses of Angkor Wat (เขมรโบราณ)',
        'legend',
        'เสียมราฐ (กัมพูชา)',
        'Siem Reap (Cambodia)',
        'พระนครวัด',
        'Angkor Wat',
        13.3675,
        103.8217,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง เสียมราฐ (กัมพูชา) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว เขมรโบราณ ใน พระนครวัด',
        'A legendary monumental marvel in Siem Reap (Cambodia). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral เขมรโบราณ engineers in Angkor Wat.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ เสียมราฐ (กัมพูชา) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Siem Reap (Cambodia), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ พระนครวัด',
        'Do not deface, carve, or displace ancient stones in Angkor Wat.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"กำแพงศิลาและป้อมปราการแห่งกษัตริย์ พระนครวัด (เขมรโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-manali-18-176',
        'พระธาตุยอดเขาพันยอด มะนาลี (เวทหิมาลัย)',
        'The Thousand-Spire Mountain Pagoda of Manali (เวทหิมาลัย)',
        'sacred',
        'หิมาจัลประเทศ (อินเดีย)',
        'Himachal Pradesh (India)',
        'มะนาลี',
        'Manali',
        32.2096,
        77.1887,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน หิมาจัลประเทศ (อินเดีย) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว เวทหิมาลัย เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Himachal Pradesh (India), serving as the spiritual heart of ancestral เวทหิมาลัย heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค หิมาจัลประเทศ (อินเดีย) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Himachal Pradesh (India), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน มะนาลี',
        'Remove footwear and maintain silence within the inner terrace of Manali.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"พระธาตุยอดเขาพันยอด มะนาลี (เวทหิมาลัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
