      ) VALUES (
        'pin-ghost-jaipur-18-177',
        'ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ ชัยปุระ (ราชปุต)',
        'The Will-o''-the-Wisp Ghost Light of Jaipur (ราชปุต)',
        'ghost',
        'ราชสถาน (อินเดีย)',
        'Rajasthan (India)',
        'ชัยปุระ',
        'Jaipur',
        26.8974,
        75.8323,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น ราชสถาน (อินเดีย) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ ชัยปุระ',
        'A chilling paranormal account from Rajasthan (India). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Jaipur.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว ราชปุต ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of ราชปุต oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ ชัยปุระ',
        'Never whistle or look back if hearing whispers along twilight pathways in Jaipur.',
        'https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg","title":"ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ ชัยปุระ (ราชปุต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LbCWDUZhSFc","title":"ปริศนาดวงวิญญาณและคฤหาสน์ต้องห้าม","thumbnail":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
